// components/MobileMenu.tsx
"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
} from "react";

type MenuLink = {
  label: string;
  href: string;
};

type MobileMenuProps = {
  links: MenuLink[];
};

type SavedStyles = {
  body: CSSProperties;
  html: CSSProperties;
};

export function MobileMenu({ links }: MobileMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const pathname = usePathname();
  const menuId = useId();

  const dialogRef = useRef<HTMLDialogElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;

    if (isOpen && !dialog.open) {
      dialog.showModal();
      closeRef.current?.focus();
    }

    if (!isOpen && dialog.open) {
      dialog.close();
      triggerRef.current?.focus();
    }
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) return;

    const body = document.body;
    const html = document.documentElement;
    const scrollbarWidth = window.innerWidth - html.clientWidth;

    const previous: SavedStyles = {
      body: {
        overflow: body.style.overflow,
        paddingRight: body.style.paddingRight,
      },
      html: {
        overflow: html.style.overflow,
        overscrollBehavior: html.style.overscrollBehavior,
      },
    };

    body.style.overflow = "hidden";
    html.style.overflow = "hidden";
    html.style.overscrollBehavior = "none";

    if (scrollbarWidth > 0) {
      body.style.paddingRight = `${scrollbarWidth}px`;
    }

    return () => {
      body.style.overflow = previous.body.overflow ?? "";
      body.style.paddingRight = previous.body.paddingRight ?? "";
      html.style.overflow = previous.html.overflow ?? "";
      html.style.overscrollBehavior =
        previous.html.overscrollBehavior ?? "";
    };
  }, [isOpen]);

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        aria-expanded={isOpen}
        aria-controls={menuId}
        aria-label="Abrir menú de navegación"
        onClick={() => setIsOpen(true)}
        className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-full border border-current px-4 text-sm font-medium focus-visible:outline-2 focus-visible:outline-offset-4 md:hidden"
      >
        Menú
      </button>

      <dialog
        ref={dialogRef}
        id={menuId}
        aria-label="Navegación principal"
        onCancel={(event) => {
          event.preventDefault();
          setIsOpen(false);
        }}
        className="fixed inset-0 m-0 h-dvh max-h-none w-screen max-w-none bg-neutral-950 p-0 text-neutral-50 backdrop:bg-neutral-950 [&[open]]:flex"
      >
        <div className="flex h-full w-full flex-col px-6 pb-8 pt-5 sm:px-10">
          <header className="flex items-center justify-between">
            <span className="text-sm uppercase tracking-[0.18em] text-neutral-400">
              Navegación
            </span>

            <button
              ref={closeRef}
              type="button"
              aria-label="Cerrar menú de navegación"
              onClick={() => setIsOpen(false)}
              className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-full border border-neutral-700 px-4 text-sm transition-colors hover:bg-neutral-50 hover:text-neutral-950 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-neutral-50"
            >
              Cerrar
            </button>
          </header>

          <nav
            aria-label="Navegación móvil"
            className="flex flex-1 items-center"
          >
            <ul className="w-full">
              {links.map(({ label, href }, index) => {
                const isCurrent = pathname === href;

                return (
                  <li key={href} className="border-b border-neutral-800">
                    <Link
                      href={href}
                      aria-current={isCurrent ? "page" : undefined}
                      onClick={() => setIsOpen(false)}
                      className="group flex min-h-16 items-center gap-5 py-5 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-neutral-50"
                    >
                      <span
                        aria-hidden="true"
                        className="text-xs tabular-nums text-neutral-500"
                      >
                        {String(index + 1).padStart(2, "0")}
                      </span>

                      <span className="text-[clamp(2.25rem,11vw,5rem)] leading-none tracking-[-0.045em] transition-transform duration-200 group-hover:translate-x-2 motion-reduce:transition-none">
                        {label}
                      </span>

                      {isCurrent ? (
                        <span className="ml-auto text-xs uppercase tracking-widest text-neutral-400">
                          Actual
                        </span>
                      ) : null}
                    </Link>
                  </li>
                );
              })}
            </ul>
          </nav>
        </div>
      </dialog>
    </>
  );
}
```

Uso:

```tsx
<MobileMenu
  links={[
    { label: "Inicio", href: "/" },
    { label: "Proyectos", href: "/proyectos" },
    { label: "Estudio", href: "/estudio" },
    { label: "Contacto", href: "/contacto" },
  ]}
/>
```

Usa `<dialog>` nativo para atrapar el foco y volver inerte el contenido de fondo. También cierra con `Escape`, restaura el foco y recupera exactamente los estilos de scroll anteriores, evitando el salto de la scrollbar.
